INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '两期平均数比较', 'kp-xingce-data-average-two-period', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "两期平均数比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "定性判断今年的平均数相比去年是上升了还是下降了。法则与“两期比重”完全相同。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目问：“2023年的平均数相比于2022年，是增加了还是减少了？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心口诀"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "分子增速 (a) > 分母增速 (b)，平均数上升。", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "分子增速 (a) < 分母增速 (b)，平均数下降。", "marks": [{"type": "bold"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题干认出两期平均数] --> B[找出分子(总数)的增速 a]\nB --> C[找出分母(份数)的增速 b]\nC --> D{比较 a 和 b 的大小}\nD -- a > b --> E[秒选: 平均数上升]\nD -- a < b --> F[秒选: 平均数下降]\nD -- a = b --> G[秒选: 平均数不变]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年旅游总收入增 15%，游客总数增 10%。问2023年人均旅游消费相比上年？选项：A. 上升 B. 下降 C. 不变 D. 无法判断"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "明确指标：人均消费 = 旅游总收入 / 游客总数。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找增速：分子(收入)增速 a = 15%，分母(人数)增速 b = 10%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比较大小：a(15%) > b(10%)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出结论：池子变大的速度比人增加的速度快，平均每个人分到的肯定多了，平均数上升。选 A。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分母增速暗藏为 0 的陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目问“1-5月的月均产值相比去年同期是上升还是下降”。材料给了产值增速15%，没给月份的增速。注意：今年是1-5月（5个月），去年同期也是1-5月（5个月），分母根本没变，b = 0%！既然 a(15%) > b(0%)，平均数自然上升。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "熟练掌握找隐藏增速 b 的技巧，特别是遇到“日均”、“月均”等时间单位作为分母时。"}]}]}$$ AS jsonb), NULL, '两期平均数比较的核心考点与实战推导。', category_node.id, CAST('["资料分析", "两期平均数比较"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_average_two_period", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
